(() => {
'use strict';
const D=window.PIPI_DATA, M=D.modules, root=document.getElementById('app');
const paths={robot:'robot',app:'app',cloud:'cloud',external:'external',vision:'vision'};
const navNames={overview:'项目总览',product:'产品概述',requirements:'产品需求',system:'系统总体架构',cloud:'皮皮猴云端',vision:'PiPi Vision',robot:'机器人端',app:'小程序 App 端',external:'外部云端',interfaces:'接口文档',models:'数据模型',progress:'开发进度',flow:'活动流程',editor:'架构管理',module:'模块架构'};
let flowStage='all', flowView='diagram', flowStep=null, flowLastStep=null;
let moduleId='';
let route='overview', selected=null, mobileMenu=false, treeOpen=true, saved={}, storageAvailable=true;
try {const raw=JSON.parse(localStorage.getItem('pipi-status-v1')||'{}'); if(raw && typeof raw==='object') for(const [k,v] of Object.entries(raw)) if(M[k] && D.statuses[v]) saved[k]=v;} catch {storageAvailable=false;}
const escape=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const svg={home:'M3 10l9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',cloud:'M7 18a5 5 0 01-1-10 7 7 0 0113 2 4 4 0 01-1 8H7',robot:'M7 7h10a3 3 0 013 3v8a3 3 0 01-3 3H7a3 3 0 01-3-3v-8a3 3 0 013-3 M12 7V3 M8 12h.01 M16 12h.01 M8 17h8 M1 12v5 M23 12v5',app:'M7 2h10a2 2 0 012 2v16a2 2 0 01-2 2H7a2 2 0 01-2-2V4a2 2 0 012-2 M9 5h6 M11 19h2',globe:'M12 2a10 10 0 100 20 10 10 0 000-20 M2 12h20 M12 2c6 6 6 14 0 20-6-6-6-14 0-20',book:'M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3V4 M12 6v16',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',vision:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 100 6 3 3 0 000-6',voice:'M9 3h6v12H9z M5 11v2a7 7 0 0014 0v-2 M12 20v3',activity:'M2 12h5l3-8 4 16 3-8h5',steps:'M4 20h5v-5h5v-5h6V4',core:'M8 8h8v8H8z M9 2v6 M15 2v6 M9 16v6 M15 16v6 M2 9h6 M2 15h6 M16 9h6 M16 15h6',database:'M3 6c0-5 18-5 18 0s-18 5-18 0 M3 6v6c0 5 18 5 18 0V6 M3 12v6c0 5 18 5 18 0v-6',user:'M12 3a4 4 0 100 8 4 4 0 000-8 M4 22v-3a8 8 0 0116 0v3',target:'M12 2a10 10 0 100 20 10 10 0 000-20 M12 7a5 5 0 100 10 5 5 0 000-10 M12 10v4 M10 12h4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',gateway:'M3 4h18v6H3z M3 14h18v6H3z M7 7h.01 M7 17h.01',chevron:'M9 5l7 7-7 7',close:'M5 5l14 14 M19 5L5 19',menu:'M3 6h18 M3 12h18 M3 18h18',link:'M10 13l4-4 M8 16l-2 2a4 4 0 01-6-6l5-5a4 4 0 016 0 M16 8l2-2a4 4 0 016 6l-5 5a4 4 0 01-6 0',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',check:'M4 12l5 5L20 6',warning:'M12 3L2 21h20L12 3 M12 9v5 M12 17h.01'};
function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${svg[n]||svg.grid}"/></svg>`;}
const status=id=>saved[id]||M[id].status;
const badge=id=>`<span class="badge ${status(id)}"><i></i>${D.statuses[status(id)]}</span>`;
function counts(){return Object.keys(D.statuses).map(s=>Object.keys(M).filter(id=>status(id)===s).length);}
function navLink(id,name,ic,sub=false){return `<a class="nav-item ${route===id?'active':''} ${sub?'sub':''}" href="#/${id}" ${route===id?'aria-current="page"':''}>${ic?icon(ic):'<span class="tree-line"></span>'}<span>${name}</span>${id==='system'?'<small>4</small>':''}</a>`;}
function architectureTree(){function branch(id,depth=0){const m=M[id],url=paths[id]||'module/'+id;return `<a class="nav-item sub ${route===url||(route==='module'&&moduleId===id)?'active':''}" style="padding-left:${22+Math.min(depth,5)*12}px" href="#/${url}"><span class="tree-line"></span><span>${m.name}</span></a>${moduleChildren(id).map(c=>branch(c,depth+1)).join('')}`;}return Object.keys(M).filter(id=>!M[id].parent).map(id=>branch(id)).join('');}
function sidebar(){return `<aside ${selected||flowStep||editState||deleteState||importState?'inert':''} class="sidebar ${mobileMenu?'visible':''}"><a class="brand" href="#/overview"><span class="brandmark">P</span><span>皮皮猴 <b>PiPi</b><small>系统架构导航台</small></span></a><div class="workspace-label">PROJECT WORKSPACE <span>V0.3</span></div><nav aria-label="项目导航">${navLink('overview','项目总览','home')}<div class="nav-caption">产品与设计</div>${navLink('product','产品概述','book')}${navLink('requirements','产品需求','file')}${navLink('flow','活动流程','steps')}<div class="nav-caption">架构与工程</div><div class="nav-tree-head">${navLink('system','系统架构','grid')}<button class="tree-toggle ${treeOpen?'open':''}" data-action="tree" aria-label="${treeOpen?'折叠':'展开'}架构导航" aria-expanded="${treeOpen}">${icon('chevron')}</button></div>${treeOpen?`<div class="tree-children">${architectureTree()}</div>`:''}${navLink('interfaces','接口文档','link')}${navLink('models','数据模型','database')}${navLink('progress','开发进度','activity')}${navLink('editor','架构管理','file')}</nav><div class="sidebar-footer"><div class="project-avatar">P</div><div>PiPi 项目空间<small>架构原型 · 示例数据</small></div></div></aside>`;}
function crumbs(){let a=[['overview','项目总览']];if(['system','cloud','vision','robot','app','external'].includes(route))a.push(['system','系统架构']);if(route==='vision')a.push(['cloud','皮皮猴云端']);if(route!=='overview'&&route!=='system')a.push([route,navNames[route]]);return a.map(([id,name],i)=>`${i?icon('chevron'):''}<a href="#/${id}" ${i===a.length-1?'aria-current="page"':''}>${name}</a>`).join('');}
function header(title,desc,label,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1 tabindex="-1">${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function moduleCard(id,compact=false){const m=M[id];return `<article class="module-card ${id==='cloud'?'accent':''} ${compact?'compact':''}"><a href="#/${paths[id]||route}" ${paths[id]?'':'data-inspect="'+id+'"'} class="card-main"><div class="card-top"><span class="module-icon ${id==='cloud'?'teal':''}">${icon(m.icon)}</span>${badge(id)}</div><h3>${m.name}</h3><span class="english">${m.en}</span><p>${m.role}</p><div class="card-bottom"><span>${paths[id]?'查看内部架构':'查看模块详情'}</span><span class="level-tag">${id==='vision'?'L3':'L2'}</span></div></a><button class="detail-button" data-inspect="${id}" aria-label="查看${m.name}职责">${icon('file')} 职责</button></article>`;}
function overview(){const c=counts();return `${editToolbar()}${header('从全局，进入每一个细节','儿童多模态互动教学智能体平台','PIPI / PROJECT OVERVIEW', '<span class="version">架构版本 <b>V0.3</b></span>')}<div class="overview-banner"><div><span class="eyebrow">ARCHITECTURE EXPLORER</span><h2>一个平台，四个协作系统</h2><p>感知、决策、交互与模型能力，在这里连接。</p><a class="button primary" href="#/system">探索总体架构 ${icon('grid')}</a></div><div class="mini-map" aria-label="四端协作示意"><span>${icon('robot')}机器人</span><i></i><strong>${icon('cloud')}PiPi Cloud</strong><i></i><span>${icon('app')}App</span><small>感知 · 决策 · 教学 · 交互</small></div></div><a class="flow-entry" href="#/flow">${icon("steps")}<span><strong>完整活动流程</strong><small>五端协作 · 六阶段 · 逐步输入输出</small></span><span>查看流程</span></a><div class="section-heading"><h2>系统入口 <small>4 个系统</small></h2><span>点击进入下一层架构</span></div><div class="system-cards">${['robot','app','cloud','external'].map(id=>moduleCard(id)).join('')}</div>${independentModules()}<div class="overview-bottom"><section class="panel"><div class="section-heading"><h2>架构层级</h2><span class="muted">由整体到实现</span></div><div class="layer-trail"><a href="#/overview"><b>L0</b><span>项目总览</span></a>${icon('chevron')}<a href="#/system"><b>L1</b><span>系统架构</span></a>${icon('chevron')}<a href="#/cloud"><b>L2</b><span>云端服务</span></a>${icon('chevron')}<a href="#/vision"><b>L3</b><span>模块实现</span></a></div></section><section class="panel"><div class="section-heading"><h2>模块状态</h2><a href="#/progress">查看进度</a></div><div class="status-counts">${Object.keys(D.statuses).map((s,i)=>`<div><strong>${c[i]}</strong><span class="badge ${s}"><i></i>${D.statuses[s]}</span></div>`).join('')}</div></section></div><div class="notice">${icon('warning')}架构和接口基于 V0.3 设计；状态为可修改的示例。硬件形态与具体接口仍需项目确认。</div>`;}
function node(id,cls=''){const m=M[id];if(!m)return '';return `<div class="graph-node ${cls} ${selected===id?'selected':''}"><button class="node-body" ${paths[id]?`data-go="${paths[id]}"`:`data-inspect="${id}"`}><span class="node-icon">${icon(m.icon)}</span><span><strong>${m.name}</strong><small>${m.en}</small></span>${paths[id]?'<span class="depth-indicator">进入</span>':''}</button><div class="node-meta">${badge(id)}<button data-inspect="${id}" aria-label="${m.name}模块详情">${icon('file')}</button></div></div>`;}
function legend(){return `<div class="diagram-footer"><span><i class="line-key"></i>核心业务流 <i class="line-key dashed"></i>能力与数据依赖</span><span>点击节点查看详情 · 标有“进入”的节点可下钻</span></div>`;}
function system(){return `${editToolbar()}${header('系统总体架构','每个系统各司其职，通过云端连接感知、教学与执行。','L1 / SYSTEM ARCHITECTURE')}<div class="graph-panel"><div class="graph-bar"><span>${icon('grid')} 四端协作架构</span><span class="version">V0.3</span></div><div class="system-graph"><div class="external-node">${node('external')}</div><div class="external-connector"><span>AI 请求 ↑ &nbsp; ↓ 模型结果</span></div><div class="system-row">${node('robot')}<div class="connection horizontal"><span>感知数据 →</span><div></div><span>← 设备控制</span></div>${node('cloud','core-node')}<div class="connection horizontal"><span>回应 / 候选 / 回执 →</span><div></div><span>← 用户操作</span></div>${node('app')}</div></div>${legend()}</div><div class="section-heading"><h2>六组核心数据流</h2><span>点击对应系统继续探索</span></div>${interfacesTable(false)}${independentModules()}<div class="notice">${icon('warning')}待确认：Camera / Microphone / Speaker 的物理归属。当前按独立机器人硬件组织职责。</div>`;}

function syncPaths(){for(const id of Object.keys(paths))if(!['robot','app','cloud','external','vision'].includes(id))delete paths[id];for(const [id,m] of Object.entries(M))if(!paths[id]&&m.children.some(c=>M[c]))paths[id]='module/'+id;}
function independentModules(){const ids=Object.keys(M).filter(id=>!M[id].parent&&!S.rootIds.includes(id));return ids.length?`<div class="section-heading"><h2>扩展模块</h2></div><div class="custom-module-grid">${ids.map(id=>moduleCard(id)).join('')}</div>`:'';}
function moduleChildren(id){return (M[id]?.children||[]).filter(c=>M[c]);}
function cloudGroup(group){return moduleChildren('cloud').filter(id=>M[id].group===group).map(id=>node(id,id==='vision'?'vision-node':id==='core'?'core-node':'')).join('')||'<span class="muted empty-group">暂无模块</span>';}

function cloud(){return `${header(M.cloud.name,M.cloud.role,'L2 / PIPI CLOUD', '<a class="button" href="#/system">返回总体架构</a>')}${editToolbar('cloud')}<div class="graph-panel"><div class="graph-bar"><span>${icon('cloud')} 云端内部架构</span><a href="#/vision" class="inline-link">探索 PiPi Vision</a></div><div class="cloud-graph"><div class="layer-label">01 <span>统一接入</span></div><div class="graph-layer single">${cloudGroup('access')}</div><div class="graph-flow">请求与数据 ↓</div><div class="layer-label">02 <span>感知与交互</span></div><div class="graph-layer two">${cloudGroup('perception')}</div><div class="graph-flow">感知事件 / 对话状态 ↓</div><div class="layer-label">03 <span>教学上下文与建议</span></div><div class="graph-layer three">${cloudGroup('teaching')}</div><div class="graph-flow">上下文 + 教学建议 ↓</div><div class="layer-label">04 <span>辅助决策</span></div><div class="graph-layer single">${cloudGroup('decision')}</div><div class="decision-label">行为建议 → 手机校验 → 组织语音 / 展示 / 设备执行</div><div class="support-layer"><div class="layer-label">05 <span>知识与基础服务</span></div><div class="graph-layer four">${cloudGroup('support')}</div></div></div>${legend()}</div><div class="notice">${icon('core')}手机负责活动推进与确认提交；云端生成建议并维护同步副本。图中向下连线表示上下文汇聚。</div>`;}
function vision(){return `${header(M.vision.name,M.vision.role,'L3 / VISION SERVICE', '<a class="button" href="#/cloud">返回云端架构</a>')}${editToolbar('vision')}<div class="vision-summary"><div>${icon('vision')}<span><strong>${M.vision.name}</strong><small>关联项目：${M.vision.project}</small></span></div>${badge('vision')}<button class="button" data-inspect="vision">服务职责</button></div><div class="graph-panel"><div class="graph-bar"><span>${icon('activity')} 视觉处理流水线</span><span class="muted">输入：Video Frame + Timestamp</span></div><div class="vision-pipeline"><div class="pipeline-label">VIDEO FRAME</div>${moduleChildren('vision').map((id,i,arr)=>node(id)+(i<arr.length-1?`<div class="pipeline-connector"><span>${M[id].output[0]||'处理结果'}</span></div>`:'')).join('')}<div class="pipeline-label output">VISION STATE / EVENT / VLM RESULT</div></div>${legend()}</div><div class="section-heading"><h2>实现组件</h2><span>职责、输入输出与依赖</span></div><div class="implementation-grid">${moduleChildren('vision').map(id=>`<button class="implementation-item" data-inspect="${id}"><span>${icon(M[id].icon)}<strong>${M[id].name}</strong></span><p>${M[id].children.join(' · ')}</p>${badge(id)}</button>`).join('')}</div><div class="notice">${icon('link')}Vision Activity Engine 只产出视觉事件。手机负责活动组织和步骤推进；云端 Activity Engine 与 Step Manager 提供上下文和同步支持。</div>`;}
function subsystem(id){const m=M[id];return `${header(m.name,m.role,'L2 / '+m.en.toUpperCase(),'<a class="button" href="#/system">返回总体架构</a>')}${editToolbar(id)}<div class="subsystem-intro panel"><span class="module-icon teal">${icon(m.icon)}</span><div><h2>${m.en}</h2><p>${m.role}</p></div>${badge(id)}<button class="button" data-inspect="${id}">系统详情</button></div><div class="section-heading"><h2>内部职责分区</h2><span>V0.3 功能划分</span></div><div class="functional-grid">${m.children.map((s,i)=>`<article class="panel"><span class="eyebrow">MODULE ${String(i+1).padStart(2,'0')}</span><h2>${M[s]?.name||s}</h2><p>${M[s]?.role||subtexts[id][i]||'职责待补充，可在系统详情中编辑。'}</p>${M[s]?`<button class="text-button" data-inspect="${s}">查看职责与输入输出</button>`:''}${M[s]?badge(s):'<span class="badge planned"><i></i>规划中</span>'}</article>`).join('')}</div>${m.note?`<div class="notice">${icon('warning')}${m.note}</div>`:''}`;}
const subtexts={robot:['采集 Camera / Microphone 数据，感知人物和环境。','语音唤醒、人物跟随，以及本地安全策略。','执行云台、电机和舵机动作，播放音频。','维护设备状态、心跳、网络配置和 OTA。'],app:['皮皮猴形象、嘴型、眼神、表情及状态动画。','组织当前提示、按需示范与双面展示。','创建活动会话，提交确认事件，暂停恢复与结束。','在用户确认后推进步骤，管理再试与检查点。','儿童与家长账户、学习记录和成长历史。','设备绑定、在线状态和设备设置。'],external:['提供实时语音识别、语言推理与语音合成。','处理高级语言推理与教学内容生成。','提供按需场景理解与视觉语义分析。','声纹识别、内容安全等辅助能力。','提供对象存储、内容分发与运行日志。']};
function interfacesTable(full=true){return `<div class="table-panel"><table><thead><tr><th>数据流方向</th><th>核心内容</th><th>交互类型</th>${full?'<th>关联模块</th>':''}</tr></thead><tbody>${D.interfaces.map(row=>`<tr><td>${row[0]}</td><td><code>${row[1]}</code></td><td>${row[2]}</td>${full?'<td>'+row[3]+'</td>':''}</tr>`).join('')}</tbody></table></div>`;}
function docs(){if(route==='product')return `${header('产品概述','皮皮猴是面向儿童的多模态互动教学智能体平台。','PRODUCT / OVERVIEW')}<div class="product-statement panel"><span class="eyebrow">PIPI PLATFORM</span><h2>看到孩子的操作，理解当前情境，<br>在合适的时刻给予引导。</h2><p>机器人感知与执行，App 组织活动并呈现互动，云端提供教学建议，外部模型提供智能能力。</p></div><div class="functional-grid">${[['感知现实世界','视频、音频和设备状态共同构成会话上下文。'],['组织教学过程','活动和步骤管理形成有序、可追踪的教学流程。'],['主动提供帮助','结合视觉证据、当前步骤和历史记忆生成提示。']].map(([a,b])=>`<article class="panel"><h2>${a}</h2><p>${b}</p></article>`).join('')}</div><div class="notice">${icon('file')}本页为产品说明骨架，可随真实需求和硬件方案继续补充。</div>`;
if(route==='requirements')return `${header('产品需求','将产品能力映射到负责它的系统与服务。','PRODUCT / REQUIREMENTS')}<div class="table-panel"><table><thead><tr><th>能力</th><th>预期行为</th><th>负责模块</th><th>设计状态</th></tr></thead><tbody>${[['多模态感知','识别教学对象与操作状态','vision'],['实时语音互动','接收儿童语音，生成对话与播报','voice'],['教学流程','手机确认后推进；云端提供规则与证据建议','phone-step'],['主动引导','云端给出建议，手机校验后组织提示','core'],['设备管理','设备绑定、状态查询与配置同步','device'],['数字人表现','根据 UI 和教学状态呈现表情与动画','app']].map(([a,b,id])=>`<tr><td>${a}</td><td>${b}</td><td><button class="text-button" data-inspect="${id}">${M[id]?.name||'关联模块已删除'}</button></td><td><span class="badge planned"><i></i>待细化</span></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('file')}需求为架构映射草案，验收标准、优先级和版本计划待补充。</div>`;
if(route==='interfaces')return `${header('接口文档','以六组核心数据流作为接口设计的起点。','ENGINEERING / INTERFACES')}${interfacesTable()}<div class="notice">${icon('file')}当前为接口职责草案。协议、路径、鉴权、错误码与消息格式尚未定稿。</div>`;
return `${header('数据模型','跨模块协作所需的核心实体与状态。','ENGINEERING / DATA MODELS')}<div class="model-grid">${D.models.map(([a,b,c])=>`<article class="panel model-card"><span class="module-icon">${icon('database')}</span><h2>${a}</h2><p>${c}</p><div class="field-list">${b.split(' · ').map(s=>`<code>${s}</code>`).join('')}</div><small>建议字段 · 待接口评审</small></article>`).join('')}</div>`;}
function progress(){const c=counts();return `${header('开发进度','按模块查看当前状态，修改后仅保存在当前浏览器。','ENGINEERING / PROGRESS','<button class="button" data-action="reset">恢复示例状态</button>')}<div class="progress-stats">${Object.keys(D.statuses).map((s,i)=>`<div class="panel"><span class="badge ${s}"><i></i>${D.statuses[s]}</span><strong>${c[i]}<small>模块</small></strong></div>`).join('')}</div><div class="table-panel"><table><thead><tr><th>模块</th><th>所属项目</th><th>当前状态</th><th>状态调整</th></tr></thead><tbody>${Object.entries(M).map(([id,m])=>`<tr><td><button class="text-button" data-inspect="${id}">${m.name}</button>${id==='vision-activity'?'<small class="table-note">Vision 内部</small>':''}</td><td>${m.project}</td><td>${badge(id)}</td><td><select aria-label="${m.name}${id==='vision-activity'?'视觉':''}状态" data-status="${id}">${Object.entries(D.statuses).map(([s,n])=>`<option value="${s}" ${s===status(id)?'selected':''}>${n}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('file')}这些状态是原型示例，不是已验证的开发进度。${storageAvailable?'状态修改仅在当前浏览器生效。':'浏览器存储不可用，状态修改仅在当前会话生效。'}</div>`;}
function detail(){if(!selected)return '';const id=selected,m=M[id];return `<div class="detail-backdrop" data-action="close-detail"></div><aside class="detail-panel" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><div class="detail-head"><span class="eyebrow">MODULE DETAILS</span><button class="icon-button" data-action="close-detail" aria-label="关闭模块详情">${icon('close')}</button></div><span class="module-icon teal">${icon(m.icon)}</span><h2 id="detail-title">${m.name}</h2><p class="detail-en">${m.en} · ${m.project}</p>${badge(id)}${route==='flow'&&flowLastStep?`<button class="button full" data-flow-step="${flowLastStep}">返回流程步骤 ${F.nodeById[flowLastStep].num}</button>`:''}<div class="detail-edit-actions"><button class="button primary" data-edit-module="${id}">编辑模块</button><button class="button" data-new-module="${id}">新增子模块</button>${S.rootIds.includes(id)?'':`<button class="button danger" data-delete-module="${id}">删除</button>`}</div><section><h3>职责</h3><p>${m.role}</p></section><section><h3>输入 <span>INPUT</span></h3><ul>${m.input.map(s=>`<li>${s}</li>`).join('')}</ul></section><section><h3>输出 <span>OUTPUT</span></h3><ul>${m.output.map(s=>`<li>${s}</li>`).join('')}</ul></section><section><h3>依赖模块</h3><div class="chips">${m.dependencies.length?m.dependencies.map(k=>`<button data-inspect="${k}">${M[k].name}</button>`).join(''):'<span class="muted">无已声明的内部依赖</span>'}</div></section><section><h3>子模块</h3><div class="child-list">${m.children.map(k=>M[k]?`<button data-inspect="${k}">${M[k].name}${icon('chevron')}</button>`:`<div>${k}</div>`).join('')}</div></section><section><h3>当前状态</h3><select data-status="${id}" aria-label="修改${m.name}状态">${Object.entries(D.statuses).map(([s,n])=>`<option value="${s}" ${s===status(id)?'selected':''}>${n}</option>`).join('')}</select><small class="storage-note">示例状态 · ${storageAvailable?'仅保存到当前浏览器':'仅在当前会话生效'}</small></section><section><h3>关联项目</h3><div class="project-ref">${icon('grid')}${m.project}<small>尚未关联仓库链接</small></div></section>${m.note?`<div class="notice">${icon('warning')}${m.note}</div>`:''}${paths[id]?`<a class="button primary full" href="#/${paths[id]}">进入内部架构</a>`:''}</aside>`;}
const F=window.PIPI_FLOW;
function flowKind(kind){return ({main:'主线',optional:'可选增强',validation:'待验证',decision:'判断',branch:'分支'})[kind];}
function flowEdge(e,stage){const a=F.nodeById[e.from],b=F.nodeById[e.to];if(a.stage!==stage||b.stage!==stage)return '';const ax=a.lane*F.column+16, bx=b.lane*F.column+16,ay=a.row*F.rowHeight+20,by=b.row*F.rowHeight+20,w=F.nodeWidth,h=F.nodeHeight;let path,lx,ly;
if(a.row===b.row){const forward=bx>ax,x1=forward?ax+w:ax,x2=forward?bx:bx+w,y=ay+h/2;const gapY=ay+h+22,offset=forward?9:-9;path=`M${x1} ${y}H${x1+offset}V${gapY}H${x2-offset}V${y}H${x2}`;lx=(x1+x2)/2;ly=gapY-6;}
else {const x1=ax+w/2,x2=bx+w/2,y1=ay+h,y2=by,gap=y2-17;if(Math.abs(b.row-a.row)>1){const gutter=F.width-4;path=`M${ax+w} ${ay+h/2}H${gutter}V${gap}H${x2}V${y2}`;lx=gutter-82;ly=gap-10;}else{path=`M${x1} ${y1}V${gap}H${x2}V${y2}`;lx=(x1+x2)/2;ly=gap-7;}}
return `<g class="flow-wire ${e.kind}"><path d="${path}" marker-end="url(#flow-arrow-${stage})"/><text x="${lx}" y="${ly}" text-anchor="middle">${escape(e.label)}</text></g>`;}
function flowCard(n){return `<button class="flow-card lane-${F.lanes[n.lane].id} kind-${n.kind} ${flowStep===n.id?'active':''}" data-flow-step="${n.id}" style="left:${n.lane*F.column+16}px;top:${n.row*F.rowHeight+20}px" aria-label="步骤 ${n.num} ${n.title}"><div class="flow-card-top"><span>${n.num}</span><small class="flow-kind ${n.kind}">${flowKind(n.kind)}</small></div><span class="flow-lane-caption">${F.lanes[n.lane].name}</span><strong>${n.title}</strong><div class="flow-io"><span>输入</span><p>${escape(n.input)}</p></div><div class="flow-io output"><span>输出</span><p>${escape(n.output)}</p></div></button>`;}
function stageDiagram(stage){const ns=F.nodes.filter(n=>n.stage===stage.id),height=(Math.max(...ns.map(n=>n.row))+1)*F.rowHeight+20;const branches=F.branches.filter(e=>F.nodeById[e.from].stage===stage.id);return `<section class="flow-stage" aria-labelledby="stage-${stage.id}"><div class="flow-stage-heading"><h2 id="stage-${stage.id}"><b>${stage.num}</b>${stage.name}</h2><span>${stage.desc}</span></div><div class="flow-stage-grid" style="height:${height}px"><div class="lane-backgrounds">${F.lanes.map(l=>`<div class="lane-${l.id}"></div>`).join('')}</div><svg class="flow-links" width="${F.width}" height="${height}" viewBox="0 0 ${F.width} ${height}" aria-hidden="true"><defs><marker id="flow-arrow-${stage.id}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#8da7b5"/></marker></defs>${F.edges.map(e=>flowEdge(e,stage.id)).join('')}</svg>${ns.map(flowCard).join('')}</div><div class="flow-stage-exits"><span>分支与交接</span>${branches.map(e=>`<button data-flow-step="${e.to}"><b>${e.when}</b><span>${F.nodeById[e.to].num} ${F.nodeById[e.to].title}</span></button>`).join('')}</div></section>`;}
function flowTable(stages){return `<div class="table-panel flow-table"><table><thead><tr><th>步骤与执行方</th><th>动作 / 处理</th><th>输入与来源</th><th>输出 / 接收方</th><th>判断与异常</th></tr></thead><tbody>${stages.map(s=>`<tr class="flow-table-stage"><th colspan="5">${s.num} ${s.name}</th></tr>${F.nodes.filter(n=>n.stage===s.id).map(n=>`<tr><td><button class="text-button" data-flow-step="${n.id}">${n.num} ${n.title}</button><small>${F.lanes[n.lane].name} · ${flowKind(n.kind)}</small></td><td>${n.process}</td><td>${n.input}</td><td>${n.output}</td><td>${n.exceptions}</td></tr>`).join('')}`).join('')}</tbody></table></div>`;}
function activityFlow(){const stages=F.stages.filter(s=>flowStage==='all'||s.id===flowStage);return `${header('完整活动流程','手机组织活动并提交确认事实，云端提供辅助建议与同步记录。','ACTIVITY / END-TO-END FLOW','<span class="version">流程设计 <b>V0.3</b></span>')}<div class="flow-ownership"><div>${icon('app')}<span><strong>手机：唯一推进与确认提交</strong><small>当前步骤 · 确认事件 · 检查点 · 本地队列</small></span></div><div>${icon('cloud')}<span><strong>云端：辅助建议与同步副本</strong><small>活动内容 · 模型接入 · 证据候选 · 相关记忆</small></span></div></div><div class="flow-controls"><div class="flow-stage-tabs" role="group" aria-label="选择活动阶段"><button data-flow-stage="all" class="${flowStage==='all'?'active':''}" aria-pressed="${flowStage==='all'}">全部阶段</button>${F.stages.map(s=>`<button data-flow-stage="${s.id}" class="${flowStage===s.id?'active':''}" aria-pressed="${flowStage===s.id}">${s.num} ${s.name.split('与')[0]}</button>`).join('')}</div><div class="flow-view-tabs" role="group" aria-label="流程显示方式"><button data-flow-view="diagram" class="${flowView==='diagram'?'active':''}" aria-pressed="${flowView==='diagram'}">${icon('grid')}泳道图</button><button data-flow-view="table" class="${flowView==='table'?'active':''}" aria-pressed="${flowView==='table'}">${icon('file')}输入输出表</button></div></div><div class="flow-context"><span>${F.nodes.length} 个动作 · 6 个阶段 · 5 条泳道</span><span>主线 <i></i> 可选 / 待验证支路 <i class="dashed"></i> 点击步骤查看完整细节</span></div>${flowView==='diagram'?`<div class="flow-canvas" tabindex="0" aria-label="完整活动泳道图，可横向滚动查看五个端"><div class="flow-canvas-content"><div class="flow-lane-heads">${F.lanes.map(l=>`<div class="lane-${l.id}">${icon(l.icon)}<span><strong>${l.name}</strong><small>${l.desc}</small></span></div>`).join('')}</div>${stages.map(stageDiagram).join('')}</div></div><p class="flow-scroll-hint">${icon('menu')}宽屏图可横向滚动；窄屏按步骤顺序展示。输入输出表可查看完整文字。</p>`:flowTable(stages)}<section class="panel flow-branches"><div class="section-heading"><h2>判断、回路与异常去向</h2><span>跨阶段交接也在这里明确</span></div><div class="flow-branch-list">${F.branches.filter(e=>flowStage==='all'||F.nodeById[e.from].stage===flowStage).map(e=>`<div><button data-flow-step="${e.from}">${F.nodeById[e.from].num} ${F.nodeById[e.from].title}</button><span><strong>${e.when}</strong><p>${e.effect}</p></span><button data-flow-step="${e.to}">${F.nodeById[e.to].num} ${F.nodeById[e.to].title}</button></div>`).join('')}</div></section><div class="notice">${icon('warning')}媒体路线待实测：A 机器人 → 手机中转 → 自有云；B 机器人 → 自有云，手机仍组织活动。实际主采集 / 播放端由会话配置确定，图中箭头表示功能交接。</div><div class="notice">${icon('file')}依据：${F.source}。手机推进与确认提交已在本轮确定；接口字段仍是设计草案，展示机构、媒体传输、声纹推理位置与视觉能力需验证。</div>`;}
function flowDetail(){if(!flowStep)return '';const n=F.nodeById[flowStep],stage=F.stages.find(s=>s.id===n.stage);const outgoing=[...F.edges.filter(e=>e.from===n.id).map(e=>({to:e.to,when:e.label,effect:'业务交接'})),...F.branches.filter(e=>e.from===n.id)];const incoming=[...F.edges.filter(e=>e.to===n.id).map(e=>({from:e.from,label:e.label})),...F.branches.filter(e=>e.to===n.id).map(e=>({from:e.from,label:e.when}))];return `<div class="detail-backdrop" data-action="close-flow"></div><aside class="detail-panel flow-detail-panel" role="dialog" aria-modal="true" aria-labelledby="flow-detail-title" tabindex="-1"><div class="detail-head"><span class="eyebrow">STEP ${n.num} / ${stage.name}</span><button class="icon-button" data-action="close-flow" aria-label="关闭流程详情">${icon('close')}</button></div><span class="module-icon teal">${icon(F.lanes[n.lane].icon)}</span><h2 id="flow-detail-title">${n.title}</h2><p class="detail-en">${F.lanes[n.lane].name} · ${flowKind(n.kind)}</p><div class="flow-basis">${n.basis}</div><section><h3>触发与前置条件</h3><p>${n.pre}</p></section><section><h3>执行职责与处理</h3><p>${n.process}</p></section><section><h3>输入与来源 <span>INPUT</span></h3><p>${n.input}</p><div class="flow-detail-links">${incoming.map(e=>`<button data-flow-step="${e.from}"><span>${F.nodeById[e.from].num} ${F.nodeById[e.from].title}</span><small>${e.label}</small></button>`).join('')}</div></section><section><h3>输出与接收方 <span>OUTPUT</span></h3><p>${n.output}</p></section>${n.fields?`<section><h3>建议接口字段</h3><div class="field-list">${n.fields.split(' · ').map(s=>`<code>${escape(s)}</code>`).join('')}</div><small class="storage-note">待评审字段，不是定稿的接口合同</small></section>`:''}<section><h3>下一步、判断与回路</h3><div class="flow-detail-links">${outgoing.length?outgoing.map(e=>`<button data-flow-step="${e.to}"><b>${e.when}</b><span>${F.nodeById[e.to].num} ${F.nodeById[e.to].title}</span><small>${e.effect}</small></button>`).join(''):'<p>等待后续用户输入或会话调度。</p>'}</div></section><section><h3>异常与边界</h3><p>${n.exceptions}</p></section><section><h3>关联架构模块</h3><div class="chips">${n.modules.filter(id=>M[id]).map(id=>`<button data-inspect="${id}">${M[id].name}<small> · ${M[id].en}</small></button>`).join('')}</div><p class="storage-note">点击查看职责；部分模块提供内部架构入口。</p></section><section><h3>设计依据与确认情况</h3><p>${F.source}</p><p>${n.basis}</p><small class="storage-note">流程设计展示，不代表真实设备正在执行。</small></section></aside>`;}
function openFlowStep(id){if(!F.nodeById[id])return;lastFocus=document.activeElement;selected=null;flowStep=id;if(flowStage!=='all'&&flowStage!==F.nodeById[id].stage)flowStage=F.nodeById[id].stage;const canvas=root.querySelector('.flow-canvas'),xy=canvas?{left:canvas.scrollLeft,top:canvas.scrollTop}:null;render();if(xy){const c=root.querySelector('.flow-canvas');c.scrollLeft=xy.left;c.scrollTop=xy.top;}root.querySelector('.flow-detail-panel').focus();}
function closeFlowStep(){const id=flowStep;flowStep=null;const canvas=root.querySelector('.flow-canvas'),xy=canvas?{left:canvas.scrollLeft,top:canvas.scrollTop}:null;render();if(xy){const c=root.querySelector('.flow-canvas');c.scrollLeft=xy.left;c.scrollTop=xy.top;}const trigger=root.querySelector(`[data-flow-step="${id}"]`);(trigger||root.querySelector('h1')).focus({preventScroll:true});}

const S=window.PIPI_STORE;
let editState=null, deleteState=null, importState=null, editorFilter='all',editorMessage='';
const rawModule=id=>S.modules[id];
function effectiveData(){const data=JSON.parse(JSON.stringify(S.modules));for(const [id,value] of Object.entries(saved))if(data[id]&&D.statuses[value])data[id].status=value;return data;}
function cleanLegacy(){saved={};try{localStorage.removeItem('pipi-status-v1');}catch{storageAvailable=false;}}
function parentOfRoute(){return ['cloud','vision','robot','app','external'].includes(route)?route:'';}
function descendantOf(id,parent){let cursor=S.modules[id]?.parent;while(cursor){if(cursor===parent)return true;cursor=S.modules[cursor]?.parent;}return false;}
function editToolbar(parent=''){return `<div class="architecture-tools"><span>${icon('file')}可直接修改模块与层级</span><div><button class="button" data-new-module="${parent}">新增模块</button><a class="button" href="#/editor">管理架构</a></div></div>`;}
function customPage(){const m=M[moduleId];if(!m)return `${header('模块已移除','可以在架构管理中撤销上一次操作。','ARCHITECTURE')}<a class="button" href="#/editor">打开架构管理</a>`;const children=m.children.filter(id=>M[id]);return `${header(m.name,m.role,'MODULE / '+m.en,`<button class="button" data-edit-module="${moduleId}">编辑模块</button>`)}${editToolbar(moduleId)}<div class="subsystem-intro panel"><span class="module-icon teal">${icon(m.icon)}</span><div><h2>${m.name}</h2><p>${m.role}</p></div>${badge(moduleId)}<button class="button" data-inspect="${moduleId}">模块详情</button></div><div class="section-heading"><h2>子模块</h2><span>${children.length} 个模块</span></div><div class="custom-module-grid">${children.map(id=>moduleCard(id)).join('')}</div>${!children.length?'<div class="editor-empty">还没有子模块，点击“新增模块”继续细化。</div>':''}<div class="panel editor-components"><h2>内部组件</h2><div class="chips">${m.children.filter(id=>!M[id]).map(s=>`<span>${s}</span>`).join('')||'<span class="muted">未填写内部组件</span>'}</div></div>`;}
function editorPage(){const list=Object.entries(M).filter(([id])=>editorFilter==='all'||id===editorFilter||descendantOf(id,editorFilter));return `${header('架构管理','新增模块、调整层级与依赖，并直接修改职责和输入输出。','ARCHITECTURE / EDITOR',`<button class="button primary" data-new-module="${editorFilter==='all'?'':editorFilter}">新增模块</button>`)}<div class="editor-save-note"><span>${icon('check')}${S.persistent?'修改自动保存在当前浏览器':'存储不可用：仅在当前会话生效，请导出备份'}</span><small>导出配置可分享；导入后在对方浏览器继续编辑。</small></div><div class="editor-controls"><label>所属系统 <select id="editor-filter">${[['all','全部模块'],...['robot','app','cloud','external'].map(id=>[id,M[id].name])].map(([id,n])=>`<option value="${id}" ${id===editorFilter?'selected':''}>${n}</option>`).join('')}</select></label><div><button class="button" data-action="undo-architecture" ${S.canUndo?'':'disabled'}>撤销上次修改</button><button class="button" data-action="export-architecture">导出配置</button><button class="button" data-action="import-architecture">导入配置</button><input type="file" id="architecture-file" accept=".json,application/json" hidden></div></div>${editorMessage?`<div class="editor-alert" role="status">${escape(editorMessage)}</div>`:''}${S.loadError?`<div class="editor-alert">${S.loadError}</div>`:''}<div class="table-panel editor-table"><table><thead><tr><th>模块</th><th>所属模块 / 分区</th><th>职责</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.map(([id,m])=>`<tr><td><button class="text-button" data-inspect="${id}">${m.name}</button><small>${m.en} · ${m.project||'未关联项目'}</small></td><td>${m.parent?M[m.parent]?.name:'系统入口 / 独立模块'}${m.parent==='cloud'?'<small>'+S.groups[m.group]+'</small>':''}</td><td>${m.role}</td><td>${badge(id)}</td><td><div class="editor-row-actions"><button class="text-button" data-edit-module="${id}">编辑</button>${S.rootIds.includes(id)?'<span class="protected-label">系统入口</span>':`<button class="text-button danger" data-delete-module="${id}">删除</button>`}</div></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('file')}四端与 Vision 是固定导航入口，可修改内容；其余模块可删除。删除会清理关联引用，子模块移到上一层，支持撤销。图形分区与 Vision 顺序会跟随配置更新。</div>`;}
function formField(name,label,value,multiline=false,required=false){return `<label class="editor-field">${label}${required?' *':''}${multiline?`<textarea name="${name}" rows="${name==='role'?3:4}" maxlength="6000" ${required?'required':''}>${escape(value)}</textarea>`:`<input name="${name}" value="${escape(value)}" maxlength="${name==='name'?100:200}" ${required?'required':''}>`}</label>`;}
function editorDialog(){if(editState){const id=editState.id,m=id?rawModule(id):{name:'',en:'',role:'',input:[],output:[],dependencies:[],children:[],project:'',note:'',parent:editState.parent,group:'support',icon:'grid',status:'planned'},parents=Object.entries(M).filter(([pid])=>pid!==id&&!descendantOf(pid,id)),locked=S.rootIds.includes(id);return `<div class="detail-backdrop" data-action="close-editor"></div><aside class="detail-panel editor-panel" role="dialog" aria-modal="true" aria-labelledby="editor-title" tabindex="-1"><div class="detail-head"><span class="eyebrow">ARCHITECTURE EDITOR</span><button class="icon-button" data-action="close-editor" aria-label="关闭编辑器">${icon('close')}</button></div><h2 id="editor-title">${id?'编辑模块':'新增模块'}</h2><p class="detail-en">保存后更新相关架构页面，模块标识保持稳定。</p><form id="module-form"><div class="editor-form-error" role="alert" hidden></div>${formField('name','模块名称',m.name,false,true)}${formField('en','副标题 / 用途',m.en)}<div class="editor-form-columns"><label class="editor-field">所属模块<select name="parent" ${locked?'disabled':''}><option value="">独立模块</option>${parents.map(([pid,pm])=>`<option value="${pid}" ${pid===m.parent?'selected':''}>${pm.name} · ${pm.en}</option>`).join('')}</select></label><label class="editor-field">云端分区<select name="group">${Object.entries(S.groups).map(([g,n])=>`<option value="${g}" ${g===m.group?'selected':''}>${n}</option>`).join('')}</select></label></div><small class="editor-hint">分区仅用于云端直属模块；修改所属模块会同步调整树形层级。</small>${formField('role','职责',m.role,true,true)}<div class="editor-form-columns">${formField('input','输入（每行一项）',m.input.join('\n'),true)}${formField('output','输出（每行一项）',m.output.join('\n'),true)}</div><fieldset class="editor-dependencies"><legend>依赖模块</legend><div>${Object.entries(M).filter(([pid])=>pid!==id).map(([pid,pm])=>`<label><input type="checkbox" name="dependencies" value="${pid}" ${m.dependencies.includes(pid)?'checked':''}><span>${pm.name}<small>${pm.en}</small></span></label>`).join('')}</div></fieldset>${formField('children','内部组件 / 子模块顺序（每行一项）',m.children.join('\n'),true)}<small class="editor-hint">可填写普通组件名称。已有子模块以标识排序；新增子模块请用“新增模块”并选择所属模块。</small><div class="editor-form-columns"><label class="editor-field">当前状态<select name="status">${Object.entries(D.statuses).map(([v,n])=>`<option value="${v}" ${v===(id?status(id):m.status)?'selected':''}>${n}</option>`).join('')}</select></label><label class="editor-field">图标<select name="icon">${S.iconNames.map(v=>`<option value="${v}" ${v===m.icon?'selected':''}>${({grid:'模块',cloud:'云',robot:'机器人',app:'手机',vision:'视觉',voice:'语音',activity:'活动',steps:'步骤',database:'数据',user:'用户',book:'知识',core:'核心',globe:'外部',target:'追踪',spark:'智能',gateway:'接入'})[v]}</option>`).join('')}</select></label></div>${formField('project','关联项目',m.project)}${formField('note','备注 / 待确认事项',m.note||'',true)}<div class="editor-form-footer"><button class="button" type="button" data-action="close-editor">取消</button><button class="button primary" type="submit">保存模块</button></div></form></aside>`;}
if(deleteState){const id=deleteState,m=M[id],deps=Object.values(M).filter(m=>m.dependencies.includes(id)).length,flows=F.nodes.filter(n=>n.modules.includes(id)).length,children=Object.values(M).filter(m=>m.parent===id).length;return `<div class="detail-backdrop" data-action="close-editor"></div><aside class="detail-panel editor-panel confirm-panel" role="dialog" aria-modal="true" aria-labelledby="editor-title" tabindex="-1"><div class="detail-head"><span class="eyebrow">DELETE MODULE</span><button class="icon-button" data-action="close-editor" aria-label="关闭删除确认">${icon('close')}</button></div><h2 id="editor-title">删除 ${m.name}？</h2><p>将清理 ${deps} 个模块的依赖引用；${flows} 个活动步骤不再显示此模块的关联。${children} 个子模块会移到上一层。</p><p>可通过“撤销上次修改”恢复。</p><div class="editor-form-footer"><button class="button" data-action="close-editor">取消</button><button class="button destructive" data-confirm-delete="${id}">确认删除</button></div></aside>`;}
if(importState)return `<div class="detail-backdrop" data-action="close-editor"></div><aside class="detail-panel editor-panel confirm-panel" role="dialog" aria-modal="true" aria-labelledby="editor-title" tabindex="-1"><div class="detail-head"><span class="eyebrow">IMPORT ARCHITECTURE</span><button class="icon-button" data-action="close-editor" aria-label="关闭导入确认">${icon('close')}</button></div><h2 id="editor-title">导入架构配置</h2><p>已校验 ${Object.keys(importState).length} 个模块。确认后替换当前浏览器中的架构配置，支持撤销。</p><div class="editor-form-footer"><button class="button" data-action="close-editor">取消</button><button class="button primary" data-action="confirm-import">确认导入</button></div></aside>`;
return '';}
function openEditor(id,parent=''){selected=null;flowStep=null;deleteState=null;importState=null;editState={id:id||null,parent};render();root.querySelector('.editor-panel').focus();}
function closeEditor(){editState=null;deleteState=null;importState=null;render();root.querySelector('h1')?.focus({preventScroll:true});}
function notifySaved(message){editorMessage=message+(S.persistent?'，已保存到当前浏览器。':'；浏览器存储不可用，请导出备份。');const alert=root.querySelector('.editor-alert');if(alert)alert.textContent=editorMessage;toast(editorMessage);}
function submitModule(form){const data=new FormData(form),split=k=>String(data.get(k)||'').split('\n').map(v=>v.trim()).filter(Boolean),id=editState.id||'module-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),next=effectiveData();const m={};for(const f of ['name','en','role','project','note','group','icon','status'])m[f]=String(data.get(f)||'').trim();m.parent=S.rootIds.includes(id)?next[id].parent:String(data.get('parent')||'');m.input=split('input');m.output=split('output');m.children=split('children');m.dependencies=data.getAll('dependencies');next[id]=m;try{S.commit(next);cleanLegacy();editState=null;selected=id;render();root.querySelector('.detail-panel').focus();notifySaved('模块已保存');}catch(e){const alert=form.querySelector('.editor-form-error');alert.textContent=e.message;alert.hidden=false;alert.scrollIntoView({block:'nearest'});}}
function exportArchitecture(){const result=S.export();result.modules=effectiveData();const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PiPi-Architecture-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('配置已导出，可导入到其他浏览器');}

function render(){syncPaths();const content=route==='overview'?overview():route==='system'?system():route==='cloud'?cloud():route==='vision'?vision():['robot','app','external'].includes(route)?subsystem(route):route==='progress'?progress():route==='flow'?activityFlow():route==='editor'?editorPage():route==='module'?customPage():docs();root.innerHTML=`${mobileMenu?'<button class="menu-backdrop" data-action="menu" aria-label="关闭导航"></button>':''}${sidebar()}<div class="main-shell" ${selected||flowStep||editState||deleteState||importState?'inert':''}><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="打开导航" aria-expanded="${mobileMenu}">${icon('menu')}</button><div class="breadcrumbs">${crumbs()}</div><span class="topbar-label">${icon('grid')} Architecture workspace</span></header><main id="main-content">${content}<footer class="page-footer"><span>PiPi · 系统架构导航台</span><span>V0.3 / 可扩展架构原型</span></footer></main></div>${detail()}${flowDetail()}${editorDialog()}`;document.title=`${navNames[route]} · 皮皮猴 PiPi`;}
function readRoute(){const next=location.hash.replace(/^#\/?/,'')||'overview';moduleId=next.startsWith('module/')?next.slice(7):'';route=moduleId?'module':navNames[next]?next:'overview';editState=null;deleteState=null;importState=null;selected=null;flowStep=null;flowLastStep=null;mobileMenu=false;render();window.scrollTo(0,0);}
let lastFocus=null;
function inspect(id){if(!M[id])return;if(flowStep)flowLastStep=flowStep;flowStep=null;lastFocus=document.activeElement;selected=id;render();root.querySelector('.detail-panel').focus();}
function closeDetail(){selected=null;render();const key=lastFocus?.dataset?.inspect;const target=key&&root.querySelector(`[data-inspect="${key}"]`);(target||root.querySelector('h1'))?.focus();}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.className='show';setTimeout(()=>el.className='',2500);}
root.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-go],[data-inspect],[data-flow-step],[data-flow-stage],[data-flow-view],[data-new-module],[data-edit-module],[data-delete-module],[data-confirm-delete]');if(!target)return;if(target.hasAttribute('data-new-module')){openEditor(null,target.dataset.newModule);return;}if(target.dataset.editModule){openEditor(target.dataset.editModule);return;}if(target.dataset.deleteModule){selected=null;flowStep=null;deleteState=target.dataset.deleteModule;render();root.querySelector('.editor-panel').focus();return;}if(target.dataset.confirmDelete){const id=target.dataset.confirmDelete;S.remove(id,effectiveData());cleanLegacy();deleteState=null;selected=null;render();notifySaved('模块已删除，可撤销恢复');return;}if(target.dataset.flowStep){openFlowStep(target.dataset.flowStep);return;}if(target.dataset.flowStage){flowStage=target.dataset.flowStage;flowStep=null;render();root.querySelector(`[data-flow-stage="${flowStage}"]`)?.focus();return;}if(target.dataset.flowView){flowView=target.dataset.flowView;render();root.querySelector(`[data-flow-view="${flowView}"]`)?.focus();return;}if(target.dataset.inspect){e.preventDefault();inspect(target.dataset.inspect);return;}if(target.dataset.go){location.hash='/'+target.dataset.go;return;}const action=target.dataset.action;if(action==='close-editor')closeEditor();if(action==='undo-architecture'){S.undo();cleanLegacy();render();notifySaved('已撤销上一次架构修改');}if(action==='export-architecture')exportArchitecture();if(action==='import-architecture')root.querySelector('#architecture-file').click();if(action==='confirm-import'){S.commit(importState);cleanLegacy();importState=null;render();notifySaved('配置已导入');}if(action==='tree'){treeOpen=!treeOpen;render();root.querySelector('.tree-toggle')?.focus();}if(action==='menu'){mobileMenu=!mobileMenu;render();}if(action==='close-detail')closeDetail();if(action==='close-flow')closeFlowStep();if(action==='reset'){saved={};try{localStorage.removeItem('pipi-status-v1');}catch{storageAvailable=false;}render();toast('已恢复示例状态');}});
root.addEventListener('change',async e=>{if(e.target.id==='editor-filter'){editorFilter=e.target.value;render();return;}if(e.target.id==='architecture-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('配置文件不能超过 2MB。');importState=S.validate(JSON.parse(await file.text()));render();root.querySelector('.editor-panel').focus();}catch(error){editorMessage='导入失败：'+(error instanceof SyntaxError?'JSON 格式无效。':error.message);render();toast(editorMessage);}return;}if(!e.target.dataset.status)return;const id=e.target.dataset.status;if(!M[id]||!D.statuses[e.target.value])return;saved[id]=e.target.value;try{localStorage.setItem('pipi-status-v1',JSON.stringify(saved));}catch{storageAvailable=false;}render();root.querySelector(`[data-status="${id}"]`)?.focus();toast(storageAvailable?'状态已保存到当前浏览器':'状态已更新，浏览器存储不可用');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(editState||deleteState||importState)closeEditor();else if(flowStep)closeFlowStep();else if(selected)closeDetail();else if(mobileMenu){mobileMenu=false;render();}}if(e.key==='Tab'&&(selected||flowStep||editState||deleteState||importState)){const panel=root.querySelector(editState||deleteState||importState?'.editor-panel':flowStep?'.flow-detail-panel':'.detail-panel');const els=[...panel.querySelectorAll('button:not([disabled]),a,select:not([disabled]),input:not([disabled]),textarea')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===panel)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
root.addEventListener('submit',e=>{if(e.target.id==='module-form'){e.preventDefault();submitModule(e.target);}});
window.addEventListener('hashchange',readRoute);readRoute();
})();
